package researchdata

// 2026-11-12: 공개 사례와 별도 사례를 분리하며, 이 참조 소스는 생성 요청에 포함하지 않는다.
func evaluationTasks() []task {
	return []task{
		{"eval-arith-double-sum", "arithmetic", "두 정수의 합을 두 배로 반환한다.", "a,b", "int,int", "int", "package main\nfunc f0(a,b int) int { return (a+b)*2 }", `[{"inputs":{"a":1,"b":2},"want":6},{"inputs":{"a":-1,"b":1},"want":0}]`, `[{"inputs":{"a":5,"b":-2},"want":6},{"inputs":{"a":-3,"b":-1},"want":-8}]`},
		{"eval-arith-reverse-diff", "arithmetic", "b에서 a를 뺀다.", "a,b", "int,int", "int", "package main\nfunc f0(a,b int) int { return b-a }", `[{"inputs":{"a":2,"b":5},"want":3},{"inputs":{"a":3,"b":1},"want":-2}]`, `[{"inputs":{"a":-3,"b":2},"want":5},{"inputs":{"a":9,"b":9},"want":0}]`},
		{"eval-arith-square-minus", "arithmetic", "정수의 제곱에서 1을 뺀다.", "x", "int", "int", "package main\nfunc f0(x int) int { return x*x-1 }", `[{"inputs":{"x":0},"want":-1},{"inputs":{"x":2},"want":3}]`, `[{"inputs":{"x":-3},"want":8},{"inputs":{"x":1},"want":0}]`},
		{"eval-arith-less-equal", "arithmetic", "a가 b 이하인지 반환한다.", "a,b", "int,int", "bool", "package main\nfunc f0(a,b int) bool { return a<=b }", `[{"inputs":{"a":1,"b":2},"want":true},{"inputs":{"a":3,"b":1},"want":false}]`, `[{"inputs":{"a":-1,"b":-1},"want":true},{"inputs":{"a":0,"b":-3},"want":false}]`},
		{"eval-branch-positive", "boolean_branch", "양수이면 1, 아니면 0을 반환한다.", "x", "int", "int", "package main\nfunc f0(x int) int { if x>0 { return 1 }; return 0 }", `[{"inputs":{"x":1},"want":1},{"inputs":{"x":0},"want":0}]`, `[{"inputs":{"x":-2},"want":0},{"inputs":{"x":9},"want":1}]`},
		{"eval-branch-negative", "boolean_branch", "음수이면 참이다.", "x", "int", "bool", "package main\nfunc f0(x int) bool { return x<0 }", `[{"inputs":{"x":-1},"want":true},{"inputs":{"x":0},"want":false}]`, `[{"inputs":{"x":-9},"want":true},{"inputs":{"x":4},"want":false}]`},
		{"eval-branch-sign-flip", "boolean_branch", "flag가 참이면 x의 부호를 바꾸고 아니면 그대로 반환한다.", "flag,x", "bool,int", "int", "package main\nfunc f0(flag bool,x int) int { if flag { return 0-x }; return x }", `[{"inputs":{"flag":true,"x":2},"want":-2},{"inputs":{"flag":false,"x":2},"want":2}]`, `[{"inputs":{"flag":true,"x":-3},"want":3},{"inputs":{"flag":false,"x":-1},"want":-1}]`},
		{"eval-branch-nonzero", "boolean_branch", "0이 아닌 수인지 반환한다.", "x", "int", "bool", "package main\nfunc f0(x int) bool { return x!=0 }", `[{"inputs":{"x":0},"want":false},{"inputs":{"x":1},"want":true}]`, `[{"inputs":{"x":-7},"want":true},{"inputs":{"x":8},"want":true}]`},
		{"eval-string-len-plus", "string", "문자열 byte 길이에 1을 더한다.", "s", "string", "int", "package main\nfunc f0(s string) int { return len(s)+1 }", `[{"inputs":{"s":""},"want":1},{"inputs":{"s":"ab"},"want":3}]`, `[{"inputs":{"s":"hello"},"want":6},{"inputs":{"s":"x"},"want":2}]`},
		{"eval-string-reverse-concat", "string", "b 뒤에 a를 붙인다.", "a,b", "string,string", "string", "package main\nfunc f0(a,b string) string { return b+a }", `[{"inputs":{"a":"a","b":"b"},"want":"ba"},{"inputs":{"a":"","b":"x"},"want":"x"}]`, `[{"inputs":{"a":"cat","b":"dog"},"want":"dogcat"},{"inputs":{"a":"x","b":""},"want":"x"}]`},
		{"eval-string-nonempty", "string", "문자열이 비어있지 않은지 반환한다.", "s", "string", "bool", "package main\nfunc f0(s string) bool { return s!=\"\" }", `[{"inputs":{"s":""},"want":false},{"inputs":{"s":"x"},"want":true}]`, `[{"inputs":{"s":"abc"},"want":true},{"inputs":{"s":" "},"want":true}]`},
		{"eval-string-longer", "string", "첫 문자열이 둘째보다 byte 길이가 긴지 반환한다.", "a,b", "string,string", "bool", "package main\nfunc f0(a,b string) bool { return len(a)>len(b) }", `[{"inputs":{"a":"ab","b":"x"},"want":true},{"inputs":{"a":"a","b":"bc"},"want":false}]`, `[{"inputs":{"a":"xx","b":"yy"},"want":false},{"inputs":{"a":"aaa","b":""},"want":true}]`},
		{"eval-slice-count-zero", "slice", "정수 슬라이스의 0 원소 개수를 반환한다.", "xs", "[]int", "int", "package main\nfunc f0(xs []int) int { v0:=0; for _,v1:=range xs { if v1==0 { v0++ } }; return v0 }", `[{"inputs":{"xs":[0,1,0]},"want":2},{"inputs":{"xs":[]},"want":0}]`, `[{"inputs":{"xs":[1,2]},"want":0},{"inputs":{"xs":[0,0,0]},"want":3}]`},
		{"eval-slice-negative-sum", "slice", "정수 슬라이스의 음수 원소 합을 반환한다.", "xs", "[]int", "int", "package main\nfunc f0(xs []int) int { v0:=0; for _,v1:=range xs { if v1<0 { v0+=v1 } }; return v0 }", `[{"inputs":{"xs":[-1,2,-3]},"want":-4},{"inputs":{"xs":[]},"want":0}]`, `[{"inputs":{"xs":[1,2]},"want":0},{"inputs":{"xs":[-5,-2]},"want":-7}]`},
		{"eval-slice-first-or-zero", "slice", "슬라이스의 첫 원소를 반환하며 비어 있으면 0을 반환한다.", "xs", "[]int", "int", "package main\nfunc f0(xs []int) int { if len(xs)==0 { return 0 }; return xs[0] }", `[{"inputs":{"xs":[]},"want":0},{"inputs":{"xs":[3,4]},"want":3}]`, `[{"inputs":{"xs":[-2]},"want":-2},{"inputs":{"xs":[9,0]},"want":9}]`},
		{"eval-slice-length-plus", "slice", "슬라이스 길이에 1을 더한다.", "xs", "[]int", "int", "package main\nfunc f0(xs []int) int { return len(xs)+1 }", `[{"inputs":{"xs":[]},"want":1},{"inputs":{"xs":[1,2]},"want":3}]`, `[{"inputs":{"xs":[5]},"want":2},{"inputs":{"xs":[1,2,3]},"want":4}]`},
		{"eval-map-size", "map_loop", "맵에 들어있는 원소 개수를 반환한다.", "m", "map[string]int", "int", "package main\nfunc f0(m map[string]int) int { return len(m) }", `[{"inputs":{"m":{}},"want":0},{"inputs":{"m":{"a":1}},"want":1}]`, `[{"inputs":{"m":{"a":1,"b":0}},"want":2},{"inputs":{"m":{"z":9}},"want":1}]`},
		{"eval-map-positive-count", "map_loop", "맵에서 양수 값의 개수를 반환한다.", "m", "map[string]int", "int", "package main\nfunc f0(m map[string]int) int { v0:=0; for _,v1:=range m { if v1>0 { v0++ } }; return v0 }", `[{"inputs":{"m":{"a":1,"b":0}},"want":1},{"inputs":{"m":{}},"want":0}]`, `[{"inputs":{"m":{"x":2,"y":3}},"want":2},{"inputs":{"m":{"z":-1}},"want":0}]`},
		{"eval-map-negative-sum", "map_loop", "맵에서 음수 값의 합을 반환한다.", "m", "map[string]int", "int", "package main\nfunc f0(m map[string]int) int { v0:=0; for _,v1:=range m { if v1<0 { v0+=v1 } }; return v0 }", `[{"inputs":{"m":{"a":-1,"b":2}},"want":-1},{"inputs":{"m":{}},"want":0}]`, `[{"inputs":{"m":{"a":-2,"b":-3}},"want":-5},{"inputs":{"m":{"x":1}},"want":0}]`},
		{"eval-map-sum-plus", "map_loop", "맵의 모든 값의 합에 1을 더한다.", "m", "map[string]int", "int", "package main\nfunc f0(m map[string]int) int { v0:=1; for _,v1:=range m { v0+=v1 }; return v0 }", `[{"inputs":{"m":{"a":2}},"want":3},{"inputs":{"m":{}},"want":1}]`, `[{"inputs":{"m":{"a":-2,"b":4}},"want":3},{"inputs":{"m":{"a":0}},"want":1}]`},
	}
}
